extra = json.load(open("/tmp/work/labels_extra.json")) if os.path.exists("/tmp/work/labels_extra.json") else {}
for slug,(cat,exp,notes) in L.items():
    d=f"{ROOT}/{slug}"
    if not os.path.isdir(d): print("missing",slug); continue
    p=json.load(open(f"{d}/pr.json")); p["category"]=cat
    with open(f"{d}/pr.json","w") as fh: json.dump(p,fh,indent=2); fh.write("\n")
    with open(f"{d}/expected.json","w") as fh: json.dump(exp,fh,indent=2); fh.write("\n")
    open(f"{d}/NOTES.md","w").write(f"# {p['repo']}#{p['number']}\n\n{notes}\n")
